import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel for element-wise addition (optional, shown for completeness)
# ----------------------------------------------------------------------
elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

elementwise_add_cuda_source = """
__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_cuda_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Custom CUDA kernel for max reduction over a dimension
# ----------------------------------------------------------------------
max_reduction_kernel_source = """
__global__ void max_reduction_kernel(const float* input, float* output, int batch_size, int dim_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float max_val = -float('inf');
        for (int i = 0; i < dim_size; ++i) {
            // Assuming input is a flat array where each row corresponds to one output element.
            float val = input[idx * dim_size + i];
            if (val > max_val) max_val = val;
        }
        output[idx] = max_val;
    }
}

torch::Tensor max_reduction_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    // Allocate an output tensor of the same shape as input.
    float* out_ptr = torch::zeros_like(x).data_ptr<float>();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    max_reduction_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out_ptr, x.size(0), dim);

    return torch::from_blob(out_ptr, x.shape()).cuda();  // placeholder for output shape
}
"""
max_reduction_cpp_source = "torch::Tensor max_reduction_cuda(torch::Tensor x, int dim);"
max_reduction = load_inline(
    name="max_reduction",
    cpp_sources=max_reduction_cpp_source,
    cuda_sources=max_reduction_kernel_source,
    functions=["max_reduction_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add  # not used in forward
        self.max_reduction = max_reduction

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.max_reduction(x, dim=self.dim)
